<template>
  <section data-museum-sheet class="museum-archive-panel" :class="{'has-content':selected || searched,'is-expanded':expanded,'is-expandable':expandable}" aria-label="Search the archive">
    <MuseumSheetHandle v-if="expandable" :expanded="expanded" label="archive" @toggle="$emit('toggle')"/>
    <form class="archive-search" role="search" @submit.prevent="search">
      <svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg>
      <input v-model="query" type="search" aria-label="Search a topic, project or place" placeholder="Search a topic, project or place" maxlength="240"/>
      <button v-if="query.trim()" type="submit" class="archive-submit" aria-label="Search the archive"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16 4v8H4m4-4-4 4 4 4"/></svg></button>
      <MuseumPanelToggle v-if="expandable" :expanded="expanded" label="archive" @toggle="$emit('toggle')"/>
      <MuseumPanelClose label="Close archive and return to the hall" @close="$emit('close')"/>
    </form>
    <p v-if="error" class="archive-status" role="status">{{ error }} <button type="button" @click="load">Try again</button></p>
    <p v-else-if="loading" class="archive-status" role="status">Opening the archive…</p>
    <div v-else-if="selected || searched" class="archive-reading">
      <article v-if="selected" class="archive-passage" :key="selected.id">
        <p class="archive-source">{{ selected.page === 'Projects' ? 'Builds' : selected.page }}</p>
        <h2>{{ selected.title }}</h2>
        <p class="archive-excerpt">{{ excerpt }}</p>
        <a :href="sourceHref" target="_blank" rel="noopener" class="archive-original">Read original <span aria-hidden="true"><ArrowUpRightIcon data-exhibition-icon /></span></a>
      </article>
      <div class="archive-nearby">
        <header><span>{{ searched ? 'Results' : 'Related material' }}</span></header>
        <p v-if="searching && !results.length" class="archive-status" role="status">Searching…</p>
        <p v-else-if="searched && !results.length" class="archive-status">Try another topic or name.</p>
        <ol><li v-for="point in listed" :key="point.id"><button type="button" :aria-pressed="point.id === selectedId" @click="choose(point.id)"><span class="archive-point" aria-hidden="true"></span><span>{{ point.title }}<small>{{ point.page === 'Projects' ? 'Builds' : point.page }}</small></span><span aria-hidden="true"><ArrowUpRightIcon data-exhibition-icon /></span></button></li></ol>
      </div>
    </div>
    <section v-else class="archive-welcome" aria-labelledby="archive-welcome-title">
      <h2 id="archive-welcome-title">Henry’s archive</h2>
      <p>A map of his work, ideas and experiences. Choose a point to read the original material and discover its connections.</p>
      <div class="archive-starting-points">
        <h3>Try a topic</h3>
        <button v-for="topic in ['AI and writing','Building things','Places and memories']" :key="topic" type="button" @click="searchTopic(topic)"><span>{{topic}}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 10h13m-5-5 5 5-5 5"/></svg></button>
      </div>
    </section>
  </section>
</template>
<script>
import Fuse from 'fuse.js';
import MuseumPanelClose from './MuseumPanelClose.vue';
import MuseumPanelToggle from './MuseumPanelToggle.vue';
import MuseumSheetHandle from './MuseumSheetHandle.vue';
import { loadMuseumArchiveRecords, nearbyArchivePoints, archiveExcerpt } from '../../utils/museumArchive';
import { viewSourceTarget } from '../../utils/viewSourceTarget';
export default {
  components: { MuseumPanelClose, MuseumPanelToggle, MuseumSheetHandle },
  props: { expandable:Boolean, expanded:Boolean, selectedId: { type: Number, default: null } },
  emits: ['toggle', 'close', 'select', 'loaded'],
  data: () => ({ records: [], query: '', searched: false, results: [], searching: false, loading: true, error: '' }),
  computed: {
    selected() { return this.records.find(point => point.id === this.selectedId); },
    excerpt() { return archiveExcerpt(this.selected); },
    sourceHref() { const target = viewSourceTarget(this.selected);return target?.href || (target ? this.$router.resolve(target).href : ''); },
    listed() { return this.searched ? this.results : nearbyArchivePoints(this.records, this.selectedId); },
  },
  watch: {
    query(value) {
      this._searchSequence = (this._searchSequence || 0) + 1;this.searching = false;
      if(!value.trim())this.clearSearch();
    },
    selectedId() { this.$nextTick(() => { const reading = this.$el?.querySelector('.archive-reading');if(reading)reading.scrollTop = 0; }); },
  },
  mounted() { this.load(); },
  beforeUnmount() { this._closed = true;this._searchSequence = (this._searchSequence || 0) + 1; },
  methods: {
    async load() {
      this.loading = true;this.error = '';
      try { const records = await loadMuseumArchiveRecords();if(this._closed)return;this.records = records;this.$emit('loaded');this._fuse = new Fuse(records, { keys: [{ name: 'title', weight: .7 }, { name: 'body', weight: .3 }], threshold: .32, ignoreLocation: true }); }
      catch { if(!this._closed)this.error = 'The archive is temporarily unavailable.'; }
      finally { if(!this._closed)this.loading = false; }
    },
    choose(id) { this.$emit('select', id, this.searched ? this.results.map(point => point.id) : []); },
    async searchTopic(topic) { this.query = topic;await this.$nextTick();this.search(); },
    clearSearch() {
      if(this.query){this.query = '';return;}
      this._searchSequence = (this._searchSequence || 0) + 1;this.searched = false;this.searching = false;this.results = [];this.$emit('select', null, []);
    },
    async search() {
      const query = this.query.trim();if(!query || !this._fuse)return;
      const sequence = (this._searchSequence || 0) + 1;this._searchSequence = sequence;
      this.searched = true;this.searching = true;
      this.results = this._fuse.search(query).slice(0, 8).map(hit => hit.item);
      if(this.results.length)this.choose(this.results[0].id);
      else this.$emit('select', null, []);
      try {
        const { semanticRank } = await import('../../utils/semanticSearch');
        const hits = await semanticRank(query, 8);
        if(this._closed || sequence !== this._searchSequence)return;
        const found = [...this.results];
        for(const hit of hits){const point = this.records.find(record => record.id === hit.id);if(point && !found.some(record => record.id === point.id))found.push(point);}
        this.results = found.slice(0, 10);
        this.$emit('select', this.results.some(point => point.id === this.selectedId) ? this.selectedId : this.results[0]?.id ?? null, this.results.map(point => point.id));
      } catch { /* The immediately available text results remain usable. */ }
      finally { if(!this._closed && sequence === this._searchSequence)this.searching = false; }
    },
  },
};
</script>
